/*
 * A032920  Numbers whose set of base-13 digits is {1,3}.
 * https://oeis.org/A032920
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the nth smallest positive integer whose base‑13 *
 *            representation uses only the digits 1 and 3. The terms are *
 *            generated by enumerating binary strings of increasing length, *
 *            mapping bit 0→digit 1 and bit 1→digit 3
 * Range:     u8 n <= 10, u16 n <= 46, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* For n < 1 the sequence is undefined; behaviour is unspecified. */
    if (n == 0) return 0;

    idx_t idx   = n;     /* 1‑based index */
    idx_t block = 2;     /* size of current block (2^len) */
    idx_t len   = 1;     /* current length in base‑13 digits */

    /* Find the block (length) that contains the nth term. */
    while (idx > block) {
        idx  -= block;   /* skip previous blocks */
        len++;           /* increase length */
        block <<= 1;     /* block size doubles */
    }

    /* Offset within the block, 0‑based. */
    idx_t offset = idx - 1;

    seq_t value = 0;
    for (idx_t i = 0; i < len; ++i) {
        idx_t bit = (offset >> (len - 1 - i)) & 1;        /* most significant bit first */
        value = value * (seq_t)13 + (seq_t)(1 + 2 * bit); /* digit = 1 if bit=0, 3 if bit=1 */
    }
    return value;
}
